-- Phase 47: food quality and traceability. Extends existing inventory,
-- procurement, kitchen, CX, hardware and analytics domains.
alter table public.plans add column if not exists food_quality_enabled boolean not null default true;
alter table public.plans add column if not exists lot_tracking_enabled boolean not null default true;
alter table public.plans add column if not exists temperature_tracking_enabled boolean not null default true;
alter table public.plans add column if not exists traceability_enabled boolean not null default true;
alter table public.plans add column if not exists internal_recall_enabled boolean not null default true;

create table public.inventory_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,name text not null,location_type text not null check(location_type in('freezer','cooler','dry_storage','cold_room','production','other')),min_temp numeric,max_temp numeric,temp_unit text not null default 'C' check(temp_unit in('C','F')),allowed_categories text[] not null default '{}',capacity_metadata jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),unique(store_id,name));
create table public.inventory_lots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,supplier_id uuid references public.suppliers(id) on delete set null,purchase_order_item_id uuid references public.purchase_order_items(id) on delete set null,purchase_receipt_item_id uuid references public.purchase_receipt_items(id) on delete set null,parent_lot_id uuid references public.inventory_lots(id) on delete set null,supplier_lot_code text,internal_lot_code text not null,received_at timestamptz,manufactured_at timestamptz,opened_at timestamptz,expiration_at timestamptz,expiration_source text check(expiration_source in('manufacturer_provided','system_calculated','manual') or expiration_source is null),quantity_received numeric not null check(quantity_received>=0),quantity_available numeric not null check(quantity_available>=0),unit text not null,status text not null default 'active' check(status in('active','quarantined','blocked','depleted','expired','recalled','discarded')),location_id uuid references public.inventory_locations(id) on delete set null,unit_cost_cents numeric,blocked_at timestamptz,blocked_by uuid references auth.users(id),block_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id,internal_lot_code));
alter table public.inventory_movements add column if not exists lot_id uuid references public.inventory_lots(id) on delete restrict;
alter table public.purchase_receipt_items add column if not exists inventory_lot_id uuid references public.inventory_lots(id) on delete set null;

create table public.quality_settings(organization_id uuid primary key references public.organizations(id) on delete cascade,traceability_mode text not null default 'basic' check(traceability_mode in('basic','lot_aware','strict_traceability')),lot_required_categories text[] not null default '{}',expiring_soon_hours integer not null default 72 check(expiring_soon_hours>0),block_expired_lots boolean not null default false,minimum_complaint_signal_sample integer not null default 3 check(minimum_complaint_signal_sample>=2),offline_entry_enabled boolean not null default false,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.quality_receiving_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,category_key text not null,require_supplier_lot boolean not null default false,require_expiration boolean not null default false,require_temperature boolean not null default false,require_condition boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,category_key));
create table public.quality_temperature_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,category_key text,inventory_item_id uuid references public.inventory_items(id) on delete cascade,context text not null check(context in('receiving','storage','preparation','holding','dispatch','custom')),min_temp numeric,max_temp numeric,unit text not null default 'C' check(unit in('C','F')),validated_by_customer boolean not null default false,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(min_temp is null or max_temp is null or min_temp<=max_temp));
create table public.temperature_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,context text not null check(context in('receiving','storage','preparation','holding','dispatch','custom')),entity_type text not null,entity_id uuid,temperature numeric not null,unit text not null default 'C' check(unit in('C','F')),measured_at timestamptz not null,measured_by uuid references auth.users(id),device_id uuid references public.hardware_devices(id) on delete set null,rule_id uuid references public.quality_temperature_rules(id) on delete set null,result text not null check(result in('pass','warning','fail','not_applicable')),notes text,idempotency_key text,created_at timestamptz not null default now(),unique(store_id,idempotency_key));
create table public.receiving_quality_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,receiving_id uuid references public.purchase_receipts(id) on delete set null,item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid references public.inventory_lots(id) on delete set null,check_type text not null,value jsonb not null default '{}',expected_rule_id uuid references public.quality_temperature_rules(id) on delete set null,result text not null check(result in('pass','warning','fail','not_applicable')),checked_by uuid references auth.users(id),checked_at timestamptz not null default now(),notes text,created_at timestamptz not null default now());
create table public.shelf_life_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,inventory_item_id uuid references public.inventory_items(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,duration_minutes integer not null check(duration_minutes>0),storage_condition text,after_opening_minutes integer check(after_opening_minutes>0),active boolean not null default true,validated_by_customer boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(inventory_item_id is not null or product_id is not null));

create table public.production_batches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,kitchen_batch_id uuid references public.kitchen_batches(id) on delete set null,output_item_id uuid not null references public.inventory_items(id) on delete restrict,output_lot_id uuid references public.inventory_lots(id) on delete set null,quantity_produced numeric not null check(quantity_produced>0),unit text not null,production_date timestamptz not null,expiration_at timestamptz,status text not null default 'completed' check(status in('planned','in_progress','completed','blocked','discarded')),produced_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.production_batch_inputs(id uuid primary key default gen_random_uuid(),production_batch_id uuid not null references public.production_batches(id) on delete restrict,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid not null references public.inventory_lots(id) on delete restrict,quantity_used numeric not null check(quantity_used>0),unit text not null,consumed_at timestamptz not null default now(),inventory_movement_id uuid references public.inventory_movements(id) on delete set null,created_at timestamptz not null default now());
alter table public.inventory_movements add column if not exists production_batch_id uuid references public.production_batches(id) on delete set null;
create table public.order_item_lot_consumptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,order_id uuid not null references public.orders(id) on delete restrict,order_item_id uuid references public.order_items(id) on delete set null,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid not null references public.inventory_lots(id) on delete restrict,production_batch_id uuid references public.production_batches(id) on delete set null,quantity_used numeric,consumed_at timestamptz not null default now(),assignment_source text not null default 'operator_confirmed' check(assignment_source in('operator_confirmed','system_suggested_confirmed','manual_historical_correction')),corrected_by uuid references auth.users(id),correction_reason text,previous_state jsonb,created_at timestamptz not null default now());

create table public.quality_nonconformities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,source_type text not null,source_id uuid,category text not null check(category in('temperature','expiration','supplier','packaging','contamination_suspected','storage','labeling','process','customer_complaint','other')),severity text not null check(severity in('low','medium','high','critical')),title text not null,description text not null,status text not null default 'open' check(status in('open','investigating','contained','corrective_action','resolved','closed')),owner_user_id uuid references auth.users(id),root_cause_hypothesis text,root_cause_confirmed boolean not null default false,detected_at timestamptz not null default now(),resolved_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.quality_corrective_actions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,nonconformity_id uuid not null references public.quality_nonconformities(id) on delete restrict,action_class text not null default 'corrective' check(action_class in('corrective','preventive')),action_type text not null check(action_type in('supplier_contact','discard','relabel','retraining','equipment_check','process_review','customer_followup','other')),description text not null,owner_user_id uuid references auth.users(id),due_at timestamptz,status text not null default 'open' check(status in('open','in_progress','completed','cancelled')),completed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.quality_inspections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,inspection_type text not null check(inspection_type in('internal','manager','supplier','custom')),checklist_id uuid references public.network_operational_standards(id) on delete set null,inspector_user_id uuid references auth.users(id),performed_at timestamptz not null,status text not null,notes text,attachments jsonb not null default '[]',created_at timestamptz not null default now());

create table public.quality_recalls(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,title text not null,reason text not null,source_lot_id uuid references public.inventory_lots(id) on delete set null,source_batch_id uuid references public.production_batches(id) on delete set null,status text not null default 'draft' check(status in('draft','investigating','active','contained','completed','cancelled')),severity text not null check(severity in('low','medium','high','critical')),impact_preview jsonb not null default '{}',confirmation_hash text,initiated_by uuid references auth.users(id),initiated_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.quality_recall_scope(id uuid primary key default gen_random_uuid(),recall_id uuid not null references public.quality_recalls(id) on delete restrict,entity_type text not null check(entity_type in('lot','batch','product','store','order')),entity_id uuid not null,impact_status text not null default 'unknown' check(impact_status in('confirmed_affected','potentially_affected','not_affected','unknown')),evidence jsonb not null default '{}',created_at timestamptz not null default now(),unique(recall_id,entity_type,entity_id));
create table public.quality_recall_store_status(id uuid primary key default gen_random_uuid(),recall_id uuid not null references public.quality_recalls(id) on delete restrict,store_id uuid not null references public.establishments(id) on delete restrict,status text not null default 'pending' check(status in('pending','acknowledged','locating','contained','completed')),quantity_located numeric,quantity_blocked numeric,quantity_discarded numeric,acknowledged_by uuid references auth.users(id),acknowledged_at timestamptz,updated_at timestamptz not null default now(),unique(recall_id,store_id));
create table public.quality_recall_tasks(id uuid primary key default gen_random_uuid(),recall_id uuid not null references public.quality_recalls(id) on delete restrict,store_id uuid references public.establishments(id) on delete restrict,task_type text not null check(task_type in('locate_stock','block','count','discard','investigate','contact_supplier','review_orders','prepare_customer_contact')),status text not null default 'open' check(status in('open','in_progress','completed','cancelled')),owner_user_id uuid references auth.users(id),due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());

create table public.quality_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.quality_offline_events(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,device_id uuid references public.offline_devices(id) on delete set null,event_type text not null,payload jsonb not null,base_version bigint,status text not null default 'pending' check(status in('pending','applied','conflict','rejected')),idempotency_key text not null,error text,created_at timestamptz not null default now(),synced_at timestamptz,unique(store_id,idempotency_key));

create table public.fact_inventory_lots(lot_id uuid primary key,organization_id uuid not null,store_id uuid not null,inventory_item_id uuid not null,status text not null,quantity_received numeric not null,quantity_available numeric not null,expiration_at timestamptz,estimated_value_cents numeric,loaded_at timestamptz not null default now());
create table public.fact_temperature_logs(log_id uuid primary key,organization_id uuid not null,store_id uuid not null,context text not null,result text not null,temperature numeric not null,measured_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_quality_checks(check_id uuid primary key,organization_id uuid not null,store_id uuid not null,check_type text not null,result text not null,checked_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_nonconformities(nonconformity_id uuid primary key,organization_id uuid not null,store_id uuid not null,category text not null,severity text not null,status text not null,detected_at timestamptz not null,resolved_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_corrective_actions(action_id uuid primary key,organization_id uuid not null,store_id uuid not null,action_type text not null,status text not null,due_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_recalls(recall_id uuid primary key,organization_id uuid not null,status text not null,severity text not null,affected_store_count integer not null default 0,affected_order_count integer not null default 0,containment_progress numeric,initiated_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_traceability_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid not null,event_type text not null,lot_id uuid,batch_id uuid,order_id uuid,complete boolean not null,occurred_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.dim_quality_category(category_key text primary key,label text not null,description text not null);
create table public.dim_storage_location(location_type text primary key,label text not null);
create table public.dim_lot_status(status text primary key,label text not null,usable boolean not null);
insert into public.dim_lot_status values ('active','Ativo',true),('quarantined','Quarentena',false),('blocked','Bloqueado',false),('depleted','Esgotado',false),('expired','Vencido',false),('recalled','Recall',false),('discarded','Descartado',false) on conflict do nothing;

create index inventory_lots_fefo_idx on public.inventory_lots(store_id,inventory_item_id,expiration_at) where status='active' and quantity_available>0;
create index inventory_lots_org_status_idx on public.inventory_lots(organization_id,status,expiration_at);
create index inventory_movements_lot_time_idx on public.inventory_movements(lot_id,created_at) where lot_id is not null;
create index production_inputs_lot_idx on public.production_batch_inputs(lot_id,consumed_at);
create index production_inputs_batch_idx on public.production_batch_inputs(production_batch_id);
create index order_lot_consumption_lot_idx on public.order_item_lot_consumptions(lot_id,consumed_at);
create index order_lot_consumption_order_idx on public.order_item_lot_consumptions(order_id,consumed_at);
create index temperature_store_time_idx on public.temperature_logs(store_id,measured_at desc);
create index nonconformity_store_status_idx on public.quality_nonconformities(store_id,status,detected_at desc);
create index recall_org_status_idx on public.quality_recalls(organization_id,status,created_at desc);
create index recall_scope_entity_idx on public.quality_recall_scope(entity_type,entity_id);
create index quality_audit_entity_idx on public.quality_audit_events(entity_type,entity_id,created_at desc);

do $$ declare t text; begin foreach t in array array['inventory_locations','inventory_lots','quality_settings','quality_receiving_requirements','quality_temperature_rules','temperature_logs','receiving_quality_checks','shelf_life_rules','production_batches','production_batch_inputs','order_item_lot_consumptions','quality_nonconformities','quality_corrective_actions','quality_inspections','quality_recalls','quality_recall_scope','quality_recall_store_status','quality_recall_tasks','quality_audit_events','quality_offline_events','fact_inventory_lots','fact_temperature_logs','fact_quality_checks','fact_nonconformities','fact_corrective_actions','fact_recalls','fact_traceability_events','dim_quality_category','dim_storage_location','dim_lot_status'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;

insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,certified,sensitive,allowed_dimensions) values
('traceability_coverage','Traceability Coverage','Cobertura comprovada, sem ocultar lacunas.','pedidos_completos / pedidos_elegiveis','fact_traceability_events','store_day','Qualidade','hourly','percent','calculation',true,true,array['store_id','date']),
('expiring_inventory_value','Expiring Inventory Value','Valor estimado de estoque próximo do vencimento.','sum(quantity_available * unit_cost)','fact_inventory_lots','lot','Qualidade','hourly','cents','calculation',true,true,array['store_id','status']),
('quality_failure_rate','Quality Failure Rate','Proporção de checks com falha.','failed_checks / total_checks','fact_quality_checks','store_day','Qualidade','hourly','percent','calculation',true,false,array['store_id','check_type']),
('receiving_rejection_rate','Receiving Rejection Rate','Recebimentos rejeitados sobre inspecionados.','rejected / inspected','fact_quality_checks','store_day','Compras','daily','percent','calculation',true,false,array['store_id']),
('open_nonconformities','Open Nonconformities','Não conformidades ainda abertas.','count(open)','fact_nonconformities','store_day','Qualidade','hourly','count','fact',true,true,array['store_id','category','severity']),
('corrective_action_completion_rate','Corrective Action Completion Rate','Ações corretivas concluídas.','completed / total','fact_corrective_actions','store_day','Qualidade','daily','percent','calculation',true,false,array['store_id','action_type']),
('temperature_exception_rate','Temperature Exception Rate','Medições fora da regra configurada.','exceptions / measurements','fact_temperature_logs','store_day','Qualidade','hourly','percent','calculation',true,false,array['store_id','context']),
('recall_containment_progress','Recall Containment Progress','Progresso operacional de contenção interna.','completed_tasks / total_tasks','fact_recalls','recall','Qualidade','hourly','percent','calculation',true,true,array['status','severity'])
on conflict(metric_key) do update set description=excluded.description,formula=excluded.formula,source_of_truth=excluded.source_of_truth;
